    tags.every(t=>r.tags.map(t=>t.trim().toLowerCase()).includes(t)) &&
    (query.versionMin===undefined || compareVersions(r.version,query.versionMin)>=0) &&
    (query.versionMax===undefined || compareVersions(r.version,query.versionMax)<=0));
